import{_ as t,a,o as s,ai as i}from"./chunks/framework.BbOtTPsL.js";const g=JSON.parse('{"title":"Build with AI","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/build-with-ai.md","filePath":"api/build-with-ai.md","lastUpdated":1781099665000}'),l={name:"api/build-with-ai.md"};function n(o,e,d,h,r,p){return s(),a("div",null,e[0]||(e[0]=[i('<h1 id="build-with-ai" tabindex="-1">Build with AI <a class="header-anchor" href="#build-with-ai" aria-label="Permalink to &quot;Build with AI&quot;">​</a></h1><p>This documentation is built to be consumed by AI coding agents (Claude Code, Cursor, Windsurf, and others) as well as humans. If you&#39;re building an app on the Bagisto API — or extending the API itself — with an AI assistant, point it at the resources below.</p><h2 id="llms-txt-—-the-machine-readable-index" tabindex="-1"><code>llms.txt</code> — the machine-readable index <a class="header-anchor" href="#llms-txt-—-the-machine-readable-index" aria-label="Permalink to &quot;`llms.txt` — the machine-readable index&quot;">​</a></h2><p>A single file lists every documented endpoint with a one-line description and a link, so an agent can discover the whole API surface in one fetch:</p><ul><li><strong>Index:</strong> <a href="/llms.txt"><code>/llms.txt</code></a> — every Shop and Admin endpoint, grouped by transport and menu.</li><li><strong>Full content:</strong> <a href="/llms-full.txt"><code>/llms-full.txt</code></a> — the complete documentation concatenated into one file for full ingestion.</li></ul><p>These follow the <a href="https://llmstxt.org" target="_blank" rel="noreferrer">llms.txt convention</a>. An agent should fetch <code>llms.txt</code> first to map the surface, then open the specific endpoint page for the exact request and response shape.</p><h2 id="agent-skills" tabindex="-1">Agent skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent skills&quot;">​</a></h2><p>The <a href="https://github.com/bagisto/bagisto-api" target="_blank" rel="noreferrer"><code>bagisto/api-agent-skills</code></a> repository packages this knowledge as installable <strong>agent skills</strong> — reusable instructions that teach an agent how to install the stack, build apps on the API, and extend the API package.</p><p>Install all skills into your agent:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/api-agent-skills</span></span></code></pre></div><p>Install for a specific agent, or a single skill:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/api-agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto/api-agent-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bagisto-api-build-app&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Skill</th><th>Use it to</th></tr></thead><tbody><tr><td><code>bagisto-api-install</code></td><td>Install Bagisto + the API package</td></tr><tr><td><code>bagisto-api-build-app</code></td><td>Build a storefront / admin / mobile / custom UI on the API</td></tr><tr><td><code>bagisto-api-develop</code></td><td>Add or extend an endpoint in the API package</td></tr><tr><td><code>bagisto-api-dev-cycle</code></td><td>Run the package&#39;s tests, lint, and cache cycle</td></tr><tr><td><code>bagisto-api-code-review</code></td><td>Review a change to the package</td></tr><tr><td><code>bagisto-api-git</code></td><td>Branch / stage / prepare a PR</td></tr></tbody></table><h2 id="optional-local-docs-mcp-server" tabindex="-1">Optional: local docs MCP server <a class="header-anchor" href="#optional-local-docs-mcp-server" aria-label="Permalink to &quot;Optional: local docs MCP server&quot;">​</a></h2><p>The skills repo also ships an <strong>optional</strong> local <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP</a> server that lets an agent search this documentation on demand — no hosting required. It indexes the API pages locally and exposes <code>search_api_docs</code>, <code>list_endpoints</code>, and <code>get_doc</code> tools.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /absolute/path/to/api-agent-skills/mcp/src/index.mjs</span></span></code></pre></div><p>You don&#39;t need the MCP server to build with AI — <code>llms.txt</code> and <code>llms-full.txt</code> cover the same need statically. See the <a href="https://github.com/bagisto/bagisto-api" target="_blank" rel="noreferrer"><code>mcp/README.md</code></a> in the skills repo for setup.</p><h2 id="how-an-agent-should-use-these-docs" tabindex="-1">How an agent should use these docs <a class="header-anchor" href="#how-an-agent-should-use-these-docs" aria-label="Permalink to &quot;How an agent should use these docs&quot;">​</a></h2><ol><li>Fetch <a href="/llms.txt"><code>/llms.txt</code></a> to discover the endpoint you need.</li><li>Open that endpoint&#39;s page for the exact request body, response shape, and errors — <strong>never guess a payload</strong>.</li><li>For end-to-end flows, follow the <a href="/api/recipes/">Recipes</a> — ordered walkthroughs that chain real endpoint calls.</li><li>Mind the GraphQL rules: select <strong>result fields</strong> (<code>cartId</code>, <code>orderId</code>, <code>success</code>) on action mutations — not <code>id</code>; inputs are camelCase; the Shop and Admin GraphQL endpoints are separate.</li></ol>',19)]))}const k=t(l,[["render",n]]);export{g as __pageData,k as default};
